target.css:
:root {
  --card-bg: #ffffff;
  --header-bg: #2d5a27;
  --tag-bg: #7ab648;
  --tag-color: #ffffff;
  --trail-name-color: #ffffff;
  --location-color: #c8e6b0;
  --badge-bg: #e05c2a;
  --badge-color: #ffffff;
  --stat-bg: #f4f9f0;
  --stat-border: #d0e8c0;
  --stat-value-color: #2d5a27;
  --stat-label-color: #6b8f5e;
  --elevation-track: #e0eed8;
  --elevation-fill: #7ab648;
  --elevation-label-color: #6b8f5e;
  --feature-bg: #edf7e5;
  --feature-color: #3a7030;
  --feature-border: #c4deb8;
  --footer-border: #e0eed8;
  --dot-good: #5ab033;
  --conditions-color: #4a6e40;
  --btn-bg: #2d5a27;
  --btn-color: #ffffff;
  --card-border: #c8dfc0;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.card {
  background: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 16px;
  width: 500px;
  overflow: hidden;
}

.card-header {
  background: var(--header-bg);
  padding: 16px 20px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}

.header-left {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tag {
  background: var(--tag-bg);
  color: var(--tag-color);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 3px 8px;
  border-radius: 20px;
  width: fit-content;
}

.trail-name {
  color: var(--trail-name-color);
  font-size: 22px;
  font-weight: 800;
  margin: 0;
  line-height: 1.2;
}

.location {
  color: var(--location-color);
  font-size: 13px;
  margin: 0;
  line-height: 1.4;
}

.difficulty-badge {
  background: var(--badge-bg);
  color: var(--badge-color);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  padding: 6px 12px;
  border-radius: 8px;
  align-self: center;
}

.stats-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  padding: 14px 20px;
  background: var(--card-bg);
}

.stat {
  background: var(--stat-bg);
  border: 1px solid var(--stat-border);
  border-radius: 10px;
  padding: 10px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.stat-value {
  color: var(--stat-value-color);
  font-size: 18px;
  font-weight: 800;
  line-height: 1;
}

.stat-label {
  color: var(--stat-label-color);
  font-size: 11px;
  font-weight: 500;
  text-align: center;
  line-height: 1.2;
}

.elevation-bar {
  margin: 0 20px 12px;
  position: relative;
}

.elevation-label {
  display: block;
  color: var(--elevation-label-color);
  font-size: 11px;
  font-weight: 600;
  margin-bottom: 6px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.elevation-fill {
  height: 10px;
  background: var(--elevation-fill);
  border-radius: 6px;
  width: 74%;
  position: relative;
}

.elevation-bar > div + span {
  color: var(--elevation-label-color);
}

.features {
  display: flex;
  gap: 8px;
  padding: 0 20px 14px;
  flex-wrap: wrap;
}

.feature {
  background: var(--feature-bg);
  color: var(--feature-color);
  border: 1px solid var(--feature-border);
  border-radius: 20px;
  padding: 5px 12px;
  font-size: 12px;
  font-weight: 600;
}

.card-footer {
  border-top: 1px solid var(--footer-border);
  padding: 12px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.conditions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.dot.good {
  background: var(--dot-good);
}

.conditions-text {
  color: var(--conditions-color);
  font-size: 13px;
  font-weight: 600;
}

.save-btn {
  background: var(--btn-bg);
  color: var(--btn-color);
  border: none;
  border-radius: 8px;
  padding: 8px 18px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}

